INSERT INTO `communication_campaigns` (`id`,`org_id`,`created_by`,`channel`,`title`,`subject`,`content`,`recipients_filter_json`,`recipients_count`,`status`,`scheduled_at`,`sent_at`,`ai_generated`,`ai_cost_euros`,`created_at`) VALUES ('1','23','2552','email','Invitation Assemblée Générale 2026','📢 Convocation AG 2026 — Votre présence compte !','Chers adhérents,\n\nNous avons le plaisir de vous convier à notre Assemblée Générale Ordinaire 2026.\n\n📅 Date : 04/07/2026\n🕐 Heure : 18h30\n📍 Lieu : Nos locaux\n\nMerci de confirmer votre présence avant le 14/05/2026.\n\nL\'équipe Solidarité Évry','{\"target\":\"all\"}','202','sent',NULL,'2025-11-19 00:30:33','0','0.0000','2026-04-07 00:30:33');
