INSERT INTO `communication_campaigns` (`id`,`org_id`,`created_by`,`channel`,`title`,`subject`,`content`,`recipients_filter_json`,`recipients_count`,`status`,`scheduled_at`,`sent_at`,`ai_generated`,`ai_cost_euros`,`created_at`) VALUES ('6','23','2552','email','Campagne dons — Noël','💝 Soutenez nos actions Noël','Cher donateur,\n\nGrâce à vos dons, nous avons pu :\n• Aider 69 familles\n• Organiser 20 ateliers\n• Accompagner 144 bénéficiaires\n\nPour continuer, nous avons besoin de votre soutien.\n\n💚 Faire un don : [lien]\n\nMerci infiniment.\n\nL\'équipe Solidarité Évry','{\"target\":\"all\"}','104','sent',NULL,'2026-04-19 00:30:33','0','0.0000','2025-04-16 00:30:33');
