INSERT INTO `ai_generated_docs` (`id`,`project_id`,`user_id`,`doc_type`,`title`,`content`,`created_at`) VALUES ('261','1281','2564','fiche_com','Fiche com — Maraude solidaire Le Havre','# 📢 Découvrez notre projet Maraude solidaire Le Havre\n\nVous voulez savoir ce que fait votre association ? Notre projet **Maraude solidaire Le Havre** illustre parfaitement notre mission.\n\n## 🎯 L\'objectif\n\nrépondre aux besoins identifiés sur le terrain\n\n## 📊 Les chiffres\n\n- 👥 60 personnes accompagnées\n- 🤝 12 bénévoles engagés\n- ⏱ 420h de présence sur le terrain\n- 💰 3177€ investis localement\n\n## 🌟 Ce qui nous rend fiers\n\nUne montée en compétences claire des bénévoles impliqués\n\nUne presse locale qui a relayé nos actions\n\n## ➡️ Comment nous rejoindre ?\n\nVous voulez contribuer ? Contactez-nous, on a forcément une mission pour vous !\n\n📧 contact@paris.fr\n🌐 assokit.fr/paris\n\n---\n**Fraternité Paris 11e · Paris**','2026-03-30 07:50:10');
