INSERT INTO `coach_reports` (`id`,`org_id`,`week_start`,`week_end`,`summary_md`,`highlights_json`,`warnings_json`,`recos_json`,`raw_response`,`generated_at`,`sent_email_at`,`generated_by`) VALUES ('4','23','2026-05-04','2026-05-10','Votre association semble au point mort : aucun adhérent, aucun projet actif, aucune activité enregistrée cette semaine. Soit vous démarrez tout juste, soit les données ne sont pas encore saisies dans Assokit. C\'est le moment de structurer les bases pour pouvoir piloter efficacement votre association.','[]','[\"Aucun adhérent enregistré : impossible de mesurer votre communauté\",\"Aucun projet actif : pas de visibilité sur vos actions en cours\",\"Aucune activité détectée : l\'outil n\'est pas alimenté\",\"Aucune campagne de cotisation : pas de revenus prévisibles\"]','[{\"icon\":\"📝\",\"title\":\"Importer votre liste d\'adhérents actuelle\",\"why\":\"Impossible de piloter sans connaître votre base réelle de membres et cotisants\"},{\"icon\":\"🎯\",\"title\":\"Créer vos 3 projets prioritaires en cours\",\"why\":\"Pour suivre l\'avancement concret et mobiliser vos bénévoles efficacement\"},{\"icon\":\"💰\",\"title\":\"Lancer une campagne de cotisations 2026\",\"why\":\"Structurer vos revenus et clarifier qui est à jour de cotisation\"}]','```json\n{\n  \"summary\": \"Votre association semble au point mort : aucun adhérent, aucun projet actif, aucune activité enregistrée cette semaine. Soit vous démarrez tout juste, soit les données ne sont pas encore saisies dans Assokit. C\'est le moment de structurer les bases pour pouvoir piloter efficacement votre association.\",\n  \"highlights\": [],\n  \"warnings\": [\n    \"Aucun adhérent enregistré : impossible de mesurer votre communauté\",\n    \"Aucun projet actif : pas de visibilité sur vos actions en cours\",\n    \"Aucune activité détectée : l\'outil n\'est pas alimenté\",\n    \"Aucune campagne de cotisation : pas de revenus prévisibles\"\n  ],\n  \"recos\": [\n    {\n      \"icon\": \"📝\",\n      \"title\": \"Importer votre liste d\'adhérents actuelle\",\n      \"why\": \"Impossible de piloter sans connaître votre base réelle de membres et cotisants\"\n    },\n    {\n      \"icon\": \"🎯\",\n      \"title\": \"Créer vos 3 projets prioritaires en cours\",\n      \"why\": \"Pour suivre l\'avancement concret et mobiliser vos bénévoles efficacement\"\n    },\n    {\n      \"icon\": \"💰\",\n      \"title\": \"Lancer une campagne de cotisations 2026\",\n      \"why\": \"Structurer vos revenus et clarifier qui est à jour de cotisation\"\n    }\n  ]\n}\n```','2026-05-12 00:08:24','2026-05-12 00:08:25',NULL);
INSERT INTO `coach_reports` (`id`,`org_id`,`week_start`,`week_end`,`summary_md`,`highlights_json`,`warnings_json`,`recos_json`,`raw_response`,`generated_at`,`sent_email_at`,`generated_by`) VALUES ('6','24','2026-05-04','2026-05-10','Semaine du 4 au 10 mai 2026 : votre association est en phase de démarrage ou de pause totale. Aucune activité détectée : 0 projet, 0 adhérent, 0 cotisation, 0 subvention. C\'est le moment idéal pour poser les bases solides ou relancer la dynamique. Sans action rapide, l\'association risque de rester inactive.','[]','[\"Aucun adhérent enregistré : l\'association n\'a pas de base de membres\",\"Aucun projet actif : pas de dynamique collective visible\",\"Aucune campagne de cotisation lancée : pas de flux financier prévu\",\"Aucune activité collaborative cette semaine : risque de désengagement\"]','[{\"icon\":\"🎯\",\"title\":\"Créer votre premier projet structurant\",\"why\":\"Un projet donne une raison concrète de mobiliser et d\'attirer des membres\"},{\"icon\":\"🤝\",\"title\":\"Enregistrer vos premiers adhérents dans Assokit\",\"why\":\"Impossible de piloter une association sans connaître sa base de membres\"},{\"icon\":\"💰\",\"title\":\"Lancer une campagne de cotisation 2026\",\"why\":\"Les cotisations assurent les ressources de base pour fonctionner\"}]','```json\n{\n  \"summary\": \"Semaine du 4 au 10 mai 2026 : votre association est en phase de démarrage ou de pause totale. Aucune activité détectée : 0 projet, 0 adhérent, 0 cotisation, 0 subvention. C\'est le moment idéal pour poser les bases solides ou relancer la dynamique. Sans action rapide, l\'association risque de rester inactive.\",\n  \"highlights\": [],\n  \"warnings\": [\n    \"Aucun adhérent enregistré : l\'association n\'a pas de base de membres\",\n    \"Aucun projet actif : pas de dynamique collective visible\",\n    \"Aucune campagne de cotisation lancée : pas de flux financier prévu\",\n    \"Aucune activité collaborative cette semaine : risque de désengagement\"\n  ],\n  \"recos\": [\n    {\n      \"icon\": \"🎯\",\n      \"title\": \"Créer votre premier projet structurant\",\n      \"why\": \"Un projet donne une raison concrète de mobiliser et d\'attirer des membres\"\n    },\n    {\n      \"icon\": \"🤝\",\n      \"title\": \"Enregistrer vos premiers adhérents dans Assokit\",\n      \"why\": \"Impossible de piloter une association sans connaître sa base de membres\"\n    },\n    {\n      \"icon\": \"💰\",\n      \"title\": \"Lancer une campagne de cotisation 2026\",\n      \"why\": \"Les cotisations assurent les ressources de base pour fonctionner\"\n    }\n  ]\n}\n```','2026-05-16 23:40:56','2026-05-12 00:08:35','2557');
INSERT INTO `coach_reports` (`id`,`org_id`,`week_start`,`week_end`,`summary_md`,`highlights_json`,`warnings_json`,`recos_json`,`raw_response`,`generated_at`,`sent_email_at`,`generated_by`) VALUES ('8','25','2026-05-04','2026-05-10','Votre association semble en phase de démarrage ou de mise en veille complète : aucun adhérent, aucun projet actif, aucune activité enregistrée cette semaine. C\'est le moment idéal pour poser les fondations si vous démarrez, ou pour relancer la dynamique si vous êtes en pause. Sans base adhérents ni projets, impossible de générer de l\'activité ou des ressources. Il faut créer l\'étincelle maintenant.','[]','[\"Aucun adhérent enregistré : sans membres, l\'association n\'a pas de communauté ni de légitimité\",\"Aucun projet actif : pas de fil conducteur pour mobiliser ou structurer l\'activité\",\"Aucune activité cette semaine : silence total sur tous les canaux de communication\",\"Aucune campagne de cotisation active : pas de mécanisme pour générer des revenus\"]','[{\"icon\":\"🎯\",\"title\":\"Enregistrer les premiers adhérents du bureau\",\"why\":\"Impossible de piloter une association sans base adhérents, même minimale : commencez par le bureau et fondateurs.\"},{\"icon\":\"📝\",\"title\":\"Créer un premier projet structurant\",\"why\":\"Un projet donne une direction concrète, mobilise l\'équipe et rend l\'association visible et crédible.\"},{\"icon\":\"💰\",\"title\":\"Lancer une campagne de cotisation 2026\",\"why\":\"Sans cotisations, pas de revenus réguliers : mettez en place le système dès maintenant pour sécuriser les ressources.\"}]','```json\n{\n  \"summary\": \"Votre association semble en phase de démarrage ou de mise en veille complète : aucun adhérent, aucun projet actif, aucune activité enregistrée cette semaine. C\'est le moment idéal pour poser les fondations si vous démarrez, ou pour relancer la dynamique si vous êtes en pause. Sans base adhérents ni projets, impossible de générer de l\'activité ou des ressources. Il faut créer l\'étincelle maintenant.\",\n  \"highlights\": [],\n  \"warnings\": [\n    \"Aucun adhérent enregistré : sans membres, l\'association n\'a pas de communauté ni de légitimité\",\n    \"Aucun projet actif : pas de fil conducteur pour mobiliser ou structurer l\'activité\",\n    \"Aucune activité cette semaine : silence total sur tous les canaux de communication\",\n    \"Aucune campagne de cotisation active : pas de mécanisme pour générer des revenus\"\n  ],\n  \"recos\": [\n    {\n      \"icon\": \"🎯\",\n      \"title\": \"Enregistrer les premiers adhérents du bureau\",\n      \"why\": \"Impossible de piloter une association sans base adhérents, même minimale : commencez par le bureau et fondateurs.\"\n    },\n    {\n      \"icon\": \"📝\",\n      \"title\": \"Créer un premier projet structurant\",\n      \"why\": \"Un projet donne une direction concrète, mobilise l\'équipe et rend l\'association visible et crédible.\"\n    },\n    {\n      \"icon\": \"💰\",\n      \"title\": \"Lancer une campagne de cotisation 2026\",\n      \"why\": \"Sans cotisations, pas de revenus réguliers : mettez en place le système dès maintenant pour sécuriser les ressources.\"\n    }\n  ]\n}\n```','2026-05-12 00:08:45','2026-05-12 00:08:45',NULL);
INSERT INTO `coach_reports` (`id`,`org_id`,`week_start`,`week_end`,`summary_md`,`highlights_json`,`warnings_json`,`recos_json`,`raw_response`,`generated_at`,`sent_email_at`,`generated_by`) VALUES ('10','26','2026-05-04','2026-05-10','Votre association démarre sur Assokit avec un tableau de bord entièrement vide : 0 projet, 0 adhérent, 0 activité cette semaine. C\'est le moment idéal pour poser les fondations : structurer votre base adhérents, lancer vos premiers projets, et activer les outils de gestion. Une page blanche, c\'est aussi une opportunité de bien faire dès le départ.','[]','[\"Aucun adhérent enregistré : impossible de piloter les cotisations ou d\'animer la communauté\",\"Aucun projet actif : pas de cap ni de mobilisation d\'équipe visible\",\"Aucune activité détectée cette semaine : la plateforme n\'est pas encore utilisée\",\"Aucune campagne de cotisation active : pas de rentrée financière prévisible\"]','[{\"icon\":\"📝\",\"title\":\"Importer ou créer votre fichier adhérents\",\"why\":\"C\'est la base de tout : cotisations, communications, statistiques et vie associative.\"},{\"icon\":\"🎯\",\"title\":\"Créer votre premier projet structurant\",\"why\":\"Un projet donne un cap, mobilise l\'équipe et permet de tester les outils collaboratifs.\"},{\"icon\":\"💰\",\"title\":\"Lancer une campagne de cotisation 2026\",\"why\":\"Sécurisez vos ressources dès maintenant pour financer vos actions à venir.\"}]','```json\n{\n  \"summary\": \"Votre association démarre sur Assokit avec un tableau de bord entièrement vide : 0 projet, 0 adhérent, 0 activité cette semaine. C\'est le moment idéal pour poser les fondations : structurer votre base adhérents, lancer vos premiers projets, et activer les outils de gestion. Une page blanche, c\'est aussi une opportunité de bien faire dès le départ.\",\n  \"highlights\": [],\n  \"warnings\": [\n    \"Aucun adhérent enregistré : impossible de piloter les cotisations ou d\'animer la communauté\",\n    \"Aucun projet actif : pas de cap ni de mobilisation d\'équipe visible\",\n    \"Aucune activité détectée cette semaine : la plateforme n\'est pas encore utilisée\",\n    \"Aucune campagne de cotisation active : pas de rentrée financière prévisible\"\n  ],\n  \"recos\": [\n    {\n      \"icon\": \"📝\",\n      \"title\": \"Importer ou créer votre fichier adhérents\",\n      \"why\": \"C\'est la base de tout : cotisations, communications, statistiques et vie associative.\"\n    },\n    {\n      \"icon\": \"🎯\",\n      \"title\": \"Créer votre premier projet structurant\",\n      \"why\": \"Un projet donne un cap, mobilise l\'équipe et permet de tester les outils collaboratifs.\"\n    },\n    {\n      \"icon\": \"💰\",\n      \"title\": \"Lancer une campagne de cotisation 2026\",\n      \"why\": \"Sécurisez vos ressources dès maintenant pour financer vos actions à venir.\"\n    }\n  ]\n}\n```','2026-05-12 00:08:56','2026-05-12 00:08:57',NULL);
INSERT INTO `coach_reports` (`id`,`org_id`,`week_start`,`week_end`,`summary_md`,`highlights_json`,`warnings_json`,`recos_json`,`raw_response`,`generated_at`,`sent_email_at`,`generated_by`) VALUES ('16','23','2026-05-11','2026-05-17','Votre association semble en phase de démarrage ou de pause complète : aucun adhérent, aucun projet actif, aucune activité détectée cette semaine. Cette situation nécessite une relance immédiate pour donner vie à la structure. Sans base d\'adhérents ni projets en cours, l\'association ne remplit pas encore sa mission. Il est temps de poser les premières briques : recruter, structurer, et lancer une première action concrète.','[]','[\"Aucun adhérent enregistré : l\'association n\'a pas encore de base humaine\",\"Aucun projet actif : pas d\'activité visible ni d\'objectif en cours\",\"Aucune campagne de cotisation lancée : pas de ressources financières prévisibles\",\"Aucune activité sur la plateforme cette semaine : risque de désengagement ou d\'abandon\"]','[{\"icon\":\"🎯\",\"title\":\"Recruter vos 10 premiers adhérents cette semaine\",\"why\":\"Sans adhérents, l\'association ne peut pas fonctionner ni justifier son existence légale et sociale.\"},{\"icon\":\"📝\",\"title\":\"Créer et lancer un premier projet pilote\",\"why\":\"Un projet concret donne du sens, mobilise les énergies et rend l\'association visible.\"},{\"icon\":\"💰\",\"title\":\"Définir et activer une campagne de cotisations\",\"why\":\"Vous avez besoin de ressources financières pour démarrer sereinement vos activités et couvrir les frais de base.\"}]','```json\n{\n  \"summary\": \"Votre association semble en phase de démarrage ou de pause complète : aucun adhérent, aucun projet actif, aucune activité détectée cette semaine. Cette situation nécessite une relance immédiate pour donner vie à la structure. Sans base d\'adhérents ni projets en cours, l\'association ne remplit pas encore sa mission. Il est temps de poser les premières briques : recruter, structurer, et lancer une première action concrète.\",\n  \"highlights\": [],\n  \"warnings\": [\n    \"Aucun adhérent enregistré : l\'association n\'a pas encore de base humaine\",\n    \"Aucun projet actif : pas d\'activité visible ni d\'objectif en cours\",\n    \"Aucune campagne de cotisation lancée : pas de ressources financières prévisibles\",\n    \"Aucune activité sur la plateforme cette semaine : risque de désengagement ou d\'abandon\"\n  ],\n  \"recos\": [\n    {\n      \"icon\": \"🎯\",\n      \"title\": \"Recruter vos 10 premiers adhérents cette semaine\",\n      \"why\": \"Sans adhérents, l\'association ne peut pas fonctionner ni justifier son existence légale et sociale.\"\n    },\n    {\n      \"icon\": \"📝\",\n      \"title\": \"Créer et lancer un premier projet pilote\",\n      \"why\": \"Un projet concret donne du sens, mobilise les énergies et rend l\'association visible.\"\n    },\n    {\n      \"icon\": \"💰\",\n      \"title\": \"Définir et activer une campagne de cotisations\",\n      \"why\": \"Vous avez besoin de ressources financières pour démarrer sereinement vos activités et couvrir les frais de base.\"\n    }\n  ]\n}\n```','2026-05-18 08:00:35','2026-05-18 08:00:35',NULL);
